def tx(s,y=165,size=15,x=38,w=519):return dict(type='text',text=s,top=y,size=size,x=x,width=w)
def space(y=600,h=160):return dict(type='box',x=38,top=y,width=519,height=h,response=True)
def table(rows,y=350,x=85,w=420,rh=38,headers=['Person letter','Age in years']):return dict(type='table',x=x,top=y,width=w,row_height=rh,headers=headers,rows=rows)
def height(labels,tops,y=555,xs=[130,370],strips=True):return dict(type='height',labels=labels,tops=tops,baseline=y,xs=xs,strips=strips)
def page(r,title,e,ids=[],stages=[],adult=False,answers=[]):
 a=T if r=='textbook' else W;n=len(a)+1
 a.append(dict(slug=f'data-{r}-{n}',kicker='Find out about our class',title=title,subtitle='Adult guidance and answers' if adult else ('Read together. Use the workbook or an exercise book.' if r=='textbook' else 'Read together. Speak, point or write here.'),elements=e+[tx(f'Page {n}',59,9,485,72)],task_ids=ids,stages=stages,adult=adult,answer_ids=answers));return n
