def assessment(mode,title,wpage,stage,intro):
 id=task('P1-19-'+mode.upper(),mode,intro+' Collect two new age replies and two new head marks, compare and record both.', 'No fixed ages or heights: obtain two NEW willing replies only after permission and the identical completed-years question; record different person letters and accurate ages with years, check back. Adult fictional roles may be home/school role-play and must not disclose replies first. Independently label two blank strips, align each bottom at a NEW upright full-size stand-in floor line, observe and mark each head top, align bottoms, compare and record both labels and correct observed relationship. Accept taller, shorter or equal as resources determine. Record actual resource help versus mathematical support and simulated versus actual collection. No resources means practical collection not assessed; copying old results does not pass.')
 for r in ['textbook','workbook']:
  page(r,title,[tx(intro+' Close model, help and earlier record pages. Use NEW replies and new head marks, not copied results.',165,14),tx(age_steps,265,12),tx(height_steps,400,12),tx('An adult provides new roles and safe full-size stand-ins without answer hints. No climbing or touching. Keep real ages private. A seated pupil may mark reachable stand-ins. No prepared resources means height collection not assessed practically.',535,10),*([space(610,165)] if r=='workbook' else [tx(f'Use workbook page {wpage}, speak or use your exercise book. An adult may record your exact words; record how you worked, not an invented success.',745,10)])],ids=[id],stages=[stage])
